insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p79', 'allemand', '3AS', 13, 79, 'L4 3AS p79 — Privater Umweltschutz kombinieren + Weniger Müll (was passt zusammen) + Fragen zum Text', E'3. Privater Umweltschutz – was gehört dazu ? Kombinieren Sie.\nPapiertüte statt Plastiktüte · Duschen statt Baden · Den Bus nehmen statt Auto fahren · Glasflasche statt Plastikflasche · Strom sparen statt Strom verschwenden · Akkus (Plural von Akkumulator) statt Batterien\n4. Weniger Müll produzieren. Wie kann man das machen ? Was passt zusammen ?\n1. Wenn man einkaufen geht, … b) … immer eine Einkaufstasche mitnehmen.\n2. Getränke… d) … nur in Glasflaschen kaufen.\n3. Brot nicht im Supermarkt, … e) … sondern beim Bäcker kaufen.\n4. Wenn man Schnupfen hat, … f) … Taschentücher aus Stoff benutzen.\n5. Wenn man ein Fest organisiert, … c) … kein Plastikgeschirr benutzen.\n6. Spielzeug … a) … aus Holz kaufen.\n7. Milch und Saft … g) … nicht in Tüten kaufen.\n8. Obst und Gemüse nicht in Dosen … h) … sondern frisch kaufen.\n5. Fragen zum Text.\n1. Warum war der Autofahrer empört ?\n2. Welche Folgen hat dieses negative Verhalten ?\n3. Weshalb sind diese Abfälle eine Gefahr für den Menschen ?\n4. Was kann man mit dem Müll machen ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
